"""Two existing registered information packs may reference one another without inline values."""
from pathlib import Path
import hashlib,json,subprocess

def run(case,r,dotnet,cli,author,check):
 root=case/'registered reference packs';root.mkdir();a=root/'a';b=root/'b';p=root/'owned'
 for d in [a,b,p]:d.mkdir()
 na='Registered.ReferenceA';nb='Registered.ReferenceB';n='Owned.ReferencePacks::';lit=lambda v:json.dumps(v,ensure_ascii=False);symbol=lambda v:'E'+hashlib.sha256(json.dumps(v,separators=(',',':')).encode()).hexdigest()[:24]
 def typename(id,kind='Information'):return'Confectory.'+kind+'.'+symbol(id.split('::')[0])+'.'+symbol(id)
 va=typename(na+'::Info');vb=typename(nb+'::Info');ra=typename(na+'::Info','Reference');rb=typename(nb+'::Info','Reference')
 (a/'Info.celem').write_text('schema '+na+'::Info {field HP single general long;field next single reference '+nb+'::Info;}');(b/'Info.celem').write_text('schema '+nb+'::Info {field HP single general long;field next single reference '+na+'::Info;}')
 for d,ns,other in [(a,na,nb),(b,nb,na)]: (d/'pack.cpack').write_text('pack '+ns+' version "1" {element Info schema "Info.celem";dependency '+other+' version "1";}')
 items={}
 def add(name,kind,source):items[name]=kind;(p/(name+'.celem')).write_text(source)
 add('NodeA','object','object '+n+'NodeA {use schema '+na+'::Info;}');add('NodeB','object','object '+n+'NodeB {use schema '+nb+'::Info;}')
 add('Main','function','function '+n+'Main () -> int {provide '+n+'Main with '+n+'MainBody;}');add('MainBody','implementation','implementation '+n+'MainBody for '+n+'Main () -> int {import Confectory.ObjectModel::Create as Create (string,string[],object[]) -> object;import '+n+'Use as Use ('+va+','+vb+') -> long;body common "Main.csbody";}')
 add('Use','function','function '+n+'Use ('+va+' left,'+vb+' right) -> long {provide '+n+'Use with '+n+'UseBody;}');add('UseBody','implementation','implementation '+n+'UseBody for '+n+'Use ('+va+' left,'+vb+' right) -> long {import Confectory.ObjectModel::Read as Read (object,string,string,string) -> object;body common "Use.csbody";}')
 manifest=p/'project.cproj';manifest.write_text('project '+n[:-2]+' version "1" {standalone true;entry '+n+'Main;'+''.join('element '+name+' '+kind+' "'+name+'.celem";'for name,kind in items.items())+''.join('registry '+ns+' '+lit(str(d/'pack.cpack'))+';dependency '+ns+' version "1";'for ns,d in [(na,a),(nb,b)])+'registry Confectory.ObjectModel '+lit(str(r/'packs/object-model/pack.cpack'))+';dependency Confectory.ObjectModel version "0.1.0";registry Confectory.Build.DotNet '+lit(str(r/'targets/dotnet/pack.cpack'))+';dependency Confectory.Build.DotNet version "0.1.0";target portable Confectory.Build.DotNet::Portable;}')
 def meta(operation,**data):
  c=subprocess.run([dotnet,str(author)],input=json.dumps(dict(operation=operation,project=str(manifest),**data)),text=True,capture_output=True,check=True);reply=json.loads(c.stdout);assert reply['ok'],reply;return reply['result']
 desc=[meta('blueprintPropertyCatalog',sourceId=n+'MainBody',owner=n+'Node'+suffix)['descriptor']for suffix in ['A','B']];contracts=[meta('informationReference',id=ns+'::Info')['descriptor']for ns in [na,nb]];fields=[next(f for f in d['fields']if f['name']=='HP')for d in desc]
 def make(d,f,number):return'calls.Create.Invoke('+lit(json.dumps(d,separators=(',',':')))+',new[]{'+lit(f['id'])+'},new object[]{'+str(number)+'L})'
 (p/'Main.csbody').write_text('object a='+make(desc[0],fields[0],10)+';object b='+make(desc[1],fields[1],21)+';var left=new '+va+' {HP=100,next='+rb+'.Bind(b,'+lit(json.dumps(contracts[1],separators=(',',':')))+')};var right=new '+vb+' {HP=200,next='+ra+'.Bind(a,'+lit(json.dumps(contracts[0],separators=(',',':')))+')};long result=calls.Use.Invoke(left,right);if(!Object.ReferenceEquals(left.next.Target,b)||!Object.ReferenceEquals(right.next.Target,a)||left.HP!=100||right.HP!=200)throw new Exception("cross-pack reference/value alias lost");Console.WriteLine(result);return checked((int)result);')
 (p/'Use.csbody').write_text('return (long)calls.Read.Invoke(left.next.Target,left.next.Owner,'+lit(fields[1]['id'])+','+lit(fields[1]['hash'])+')+(long)calls.Read.Invoke(right.next.Target,right.next.Owner,'+lit(fields[0]['id'])+','+lit(fields[0]['hash'])+');')
 protected={f:f.read_bytes()for d in [a,b,p]for f in d.iterdir()if f.is_file()};c=subprocess.run([dotnet,str(cli),'build',str(manifest),'portable'],text=True,capture_output=True);(root/'native-build.log').write_text(c.stdout+c.stderr);assert c.returncode==0,c.stdout[-5000:]+c.stderr[-1500:];report=json.loads(c.stdout);c=subprocess.run(report['run'],text=True,capture_output=True);(root/'native-run.json').write_text(json.dumps(dict(exit=c.returncode,stdout=c.stdout,stderr=c.stderr)));assert(c.returncode,c.stdout.strip())==(31,'31'),(c.returncode,c.stdout,c.stderr);assert all(f.read_bytes()==raw for f,raw in protected.items());check('two registered information packs with mutual reference fields link actual nominal carrier/value assemblies and execute31 without inline value cycles, snapshots or foreign source writes')
 raw=(a/'pack.cpack').read_bytes();(a/'pack.cpack').write_bytes(raw.replace(('dependency '+nb+' version "1";').encode(),b''));c=subprocess.run([dotnet,str(cli),'build',str(manifest),'portable'],text=True,capture_output=True);(root/'missing-dependency.log').write_text(c.stdout+c.stderr);assert c.returncode!=0 and'UNDECLARED_DEPENDENCY'in c.stdout+c.stderr;(a/'pack.cpack').write_bytes(raw);assert all(f.read_bytes()==v for f,v in protected.items());check('registered cross-pack references require both existing directional dependencies; no grants or migration are inferred from native type names')
